create table app_settings(id uuid primary key,family_id uuid not null unique references families(id),baby_nickname text,baby_official_name text,baby_sex text,birth_date date,birth_time text,birth_hospital text,theme_mode text,dashboard_config jsonb not null default '{}',cloud_config jsonb not null default '{}',smart_alert_config jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version int not null default 1,created_by_device uuid,updated_by_device uuid,last_op_id uuid,deleted_at timestamptz,lmp date,avatar_data_url text,show_official_name boolean not null default false,extra jsonb not null default '{}');
alter table app_settings enable row level security;
create trigger updated before update on app_settings for each row execute function myb_set_updated_at();
alter table care_categories add column extra jsonb not null default '{}',add column description text,add column sort_order int default 0,add column created_at timestamptz not null default now();
insert into app_settings(id,family_id,baby_nickname,extra) values(myb_stable_uuid('app_settings:main'),myb_stable_uuid('family:main'),'Bún','{"birthTimeFrom":"22:39","dashboardConfig":{"modules":[]},"retainedCustom":"keep"}');
